#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# One-time GCP setup for the preview API deploy (MarkMe M3, T016, quickstart V7).
# Run from the repo root: bash scripts/setup-gcp.sh
# Every stage checks before it creates, so a re-run is safe. No step needs or
# stores a secret: GitHub Actions signs in through Workload Identity Federation.

REPO="MostafaAbuHamed/MarkMe"
REGION="europe-west1"
AR_REPO="markme"
DEPLOY_SA_NAME="preview-api-deploy"
RUNTIME_SA_NAME="preview-api-runtime"
WIF_POOL="github"
WIF_PROVIDER="markme-repo"
PREVIEW_API_SUPABASE_URL="https://cpvcrpwysjovwohjpxru.supabase.co"
WIF_CONDITION="assertion.repository == \"$REPO\" && (assertion.ref == \"refs/heads/main\" || assertion.ref.matches(\"^refs/heads/[0-9]{3}-\"))"

# run CMD... prints a command, then runs it, so Mostafa sees every change made.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@"
}

# exists CMD... is true when a gcloud describe/list call succeeds quietly.
exists() { "$@" >/dev/null 2>&1; }

run_wizard() {

TOTAL_STAGES=10

banner "MarkMe preview API: Google Cloud setup"

stage "Check the gcloud CLI"
if ! command -v gcloud >/dev/null 2>&1; then
  warn "gcloud is not installed. Installing system software is your call, so this wizard stops here."
  say "Install it with the official instructions, then re-run this script:"
  open_url "https://cloud.google.com/sdk/docs/install#rpm"
  exit 1
fi
gcloud --version 2>/dev/null | sed -n 1p
pause

stage "Sign in to Google Cloud"
ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
if [[ -n "$ACCOUNT" ]] && ! confirm "Signed in as $ACCOUNT. Sign in with a different account?"; then
  note "keeping $ACCOUNT"
else
  say "A browser window opens; pick the Google account that should own the project."
  run gcloud auth login
fi
pause

stage "Project"
say "Project ids are global, so 'markme' may already belong to someone else."
CURRENT_PROJECT=$(gcloud config get-value project 2>/dev/null || true)
ask GCP_PROJECT_ID "Project id [${CURRENT_PROJECT:-markme}]:"
GCP_PROJECT_ID="${GCP_PROJECT_ID:-${CURRENT_PROJECT:-markme}}"
if exists gcloud projects describe "$GCP_PROJECT_ID"; then
  note "project $GCP_PROJECT_ID exists; reusing it"
else
  run gcloud projects create "$GCP_PROJECT_ID" --name="MarkMe"
fi
run gcloud config set project "$GCP_PROJECT_ID"
PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')
note "project number: $PROJECT_NUMBER"
pause

stage "Link billing"
LINKED=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingAccountName)' 2>/dev/null || true)
if [[ -n "$LINKED" ]]; then
  note "already linked to $LINKED"
  BILLING_ACCOUNT="${LINKED#billingAccounts/}"
else
  say "Your open billing accounts:"
  run gcloud billing accounts list --filter=open=true --format='table(name.basename(), displayName)'
  ask BILLING_ACCOUNT "Billing account id to link (XXXXXX-XXXXXX-XXXXXX):"
  run gcloud billing projects link "$GCP_PROJECT_ID" --billing-account="$BILLING_ACCOUNT"
fi
pause

stage "Budget: \$1 with alerts"
say "Alerts at 50%, 90% and 100% go to the billing account admins by email."
note "A budget only alerts; it does not stop spending. Cloud Run is capped at one instance."
run gcloud services enable billingbudgets.googleapis.com
if gcloud billing budgets list --billing-account="$BILLING_ACCOUNT" --format='value(displayName)' 2>/dev/null | grep -qx "markme-preview-api"; then
  note "budget markme-preview-api already exists"
else
  run gcloud billing budgets create --billing-account="$BILLING_ACCOUNT" \
    --display-name="markme-preview-api" --budget-amount=1USD \
    --filter-projects="projects/$GCP_PROJECT_ID" \
    --threshold-rule=percent=0.5 --threshold-rule=percent=0.9 --threshold-rule=percent=1.0
fi
pause

stage "Enable APIs"
run gcloud services enable run.googleapis.com artifactregistry.googleapis.com \
  iamcredentials.googleapis.com sts.googleapis.com
pause

stage "Artifact Registry"
if exists gcloud artifacts repositories describe "$AR_REPO" --location="$REGION"; then
  note "repository $AR_REPO already exists"
else
  run gcloud artifacts repositories create "$AR_REPO" --repository-format=docker \
    --location="$REGION" --description="MarkMe images"
fi
say "Cleanup policy: keep the 3 most recent versions, delete the rest."
POLICY_FILE=$(mktemp)
cat > "$POLICY_FILE" <<'JSON'
[
  { "name": "keep-3-recent", "action": { "type": "Keep" }, "mostRecentVersions": { "keepCount": 3 } },
  { "name": "delete-older", "action": { "type": "Delete" }, "condition": { "tagState": "ANY" } }
]
JSON
run gcloud artifacts repositories set-cleanup-policies "$AR_REPO" --location="$REGION" \
  --policy="$POLICY_FILE" --no-dry-run
rm -f "$POLICY_FILE"
pause

DEPLOY_SA="$DEPLOY_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
RUNTIME_SA="$RUNTIME_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"

stage "Service accounts"
say "Runtime account: the service runs as it, with no roles (not the Editor default)."
say "Deploy account: GitHub Actions acts as it to push images and deploy."
for name in "$RUNTIME_SA_NAME" "$DEPLOY_SA_NAME"; do
  if exists gcloud iam service-accounts describe "$name@$GCP_PROJECT_ID.iam.gserviceaccount.com"; then
    note "service account $name already exists"
  else
    run gcloud iam service-accounts create "$name" --display-name="$name"
  fi
done
for role in roles/run.admin roles/artifactregistry.writer; do
  run gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
    --member="serviceAccount:$DEPLOY_SA" --role="$role" --condition=None >/dev/null
done
run gcloud iam service-accounts add-iam-policy-binding "$RUNTIME_SA" \
  --member="serviceAccount:$DEPLOY_SA" --role=roles/iam.serviceAccountUser >/dev/null
pause

stage "Workload Identity Federation for GitHub"
say "Only $REPO on main or an NNN-* milestone branch may sign in."
if exists gcloud iam workload-identity-pools describe "$WIF_POOL" --location=global; then
  note "pool $WIF_POOL already exists"
else
  run gcloud iam workload-identity-pools create "$WIF_POOL" --location=global --display-name="GitHub"
fi
if exists gcloud iam workload-identity-pools providers describe "$WIF_PROVIDER" \
    --location=global --workload-identity-pool="$WIF_POOL"; then
  note "provider $WIF_PROVIDER already exists"
else
  run gcloud iam workload-identity-pools providers create-oidc "$WIF_PROVIDER" \
    --location=global --workload-identity-pool="$WIF_POOL" \
    --issuer-uri="https://token.actions.githubusercontent.com" \
    --attribute-mapping="google.subject=assertion.sub,attribute.repository=assertion.repository,attribute.ref=assertion.ref" \
    --attribute-condition="$WIF_CONDITION"
fi
POOL_PATH="projects/$PROJECT_NUMBER/locations/global/workloadIdentityPools/$WIF_POOL"
run gcloud iam service-accounts add-iam-policy-binding "$DEPLOY_SA" \
  --role=roles/iam.workloadIdentityUser \
  --member="principalSet://iam.googleapis.com/$POOL_PATH/attribute.repository/$REPO" >/dev/null
GCP_WIF_PROVIDER="$POOL_PATH/providers/$WIF_PROVIDER"
pause

stage "GitHub repository variables"
say "These are ids, not secrets. The deploy workflow reads them as vars.*"
note "GCP_PROJECT_ID=$GCP_PROJECT_ID"
note "GCP_WIF_PROVIDER=$GCP_WIF_PROVIDER"
note "GCP_DEPLOY_SA=$DEPLOY_SA"
note "PREVIEW_API_RUNTIME_SA=$RUNTIME_SA"
note "PREVIEW_API_SUPABASE_URL=$PREVIEW_API_SUPABASE_URL"
if confirm "Set these on $REPO now?"; then
  set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
  set_var GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
  set_var GCP_DEPLOY_SA "$DEPLOY_SA"
  set_var PREVIEW_API_RUNTIME_SA "$RUNTIME_SA"
  set_var PREVIEW_API_SUPABASE_URL "$PREVIEW_API_SUPABASE_URL"
  run gh variable list --repo "$REPO"
else
  SKIPPED+=("GitHub variables (re-run this stage, or gh variable set each value above)")
fi
pause

finish
}

run_wizard "$@"; exit
